from pysat.solvers import Solver
from itertools import combinations
import time
n=21
edge_var={}
idx=1
order=[]
for i in range(n):
    for j in range(i+1,n):
        edge_var[(i,j)]=idx; order.append((i,j)); idx+=1
clauses=[]
for S in combinations(range(n),5):
    clauses.append([edge_var[(i,j)] for i,j in combinations(S,2)])
for S in combinations(range(n),4):
    clauses.append([-edge_var[(i,j)] for i,j in combinations(S,2)])
print(len(clauses), idx-1)
start=time.time()
for name in ['cadical153','cadical195','glucose4','glucose3','minisat22','maplesat']:
    try:
        with Solver(name=name, bootstrap_with=clauses) as sol:
            print('solver', name, flush=True)
            sat=sol.solve()
            print('sat', sat, 'time', time.time()-start, flush=True)
            if sat:
                model=sol.get_model()
                # create assignment dict
                md={abs(l): l>0 for l in model}
                vals=[1 if md.get(v,False) else 0 for v in range(1,idx)]
                print(vals)
                break
    except Exception as e:
        print('err', name, e, flush=True)
